CREATE SCHEMA IF NOT EXISTS campus_live;
REVOKE ALL ON SCHEMA campus_live FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS campus_live.users(id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('student','teacher','admin')), password TEXT NOT NULL,class_id TEXT NOT NULL DEFAULT '10A',must_change INTEGER NOT NULL DEFAULT 0,verified INTEGER NOT NULL DEFAULT 1, google_sub TEXT, auth_source TEXT NOT NULL DEFAULT 'local-test', active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS campus_live.sessions(user_id TEXT PRIMARY KEY REFERENCES campus_live.users(id), token_hash TEXT UNIQUE NOT NULL, created DOUBLE PRECISION NOT NULL, seen DOUBLE PRECISION NOT NULL, expires DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS campus_live.limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,until DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS campus_live.attempts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES campus_live.users(id),lesson_id TEXT NOT NULL,mission_id TEXT NOT NULL,passed INTEGER NOT NULL DEFAULT 0,evidence TEXT,created DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS campus_live.submissions(user_id TEXT PRIMARY KEY REFERENCES campus_live.users(id),explanation TEXT NOT NULL,reflection TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',feedback TEXT NOT NULL DEFAULT '',revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS campus_live.audit(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor TEXT,action TEXT NOT NULL,target TEXT,at DOUBLE PRECISION NOT NULL,detail TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS campus_live.oauth_state(token_hash TEXT PRIMARY KEY,nonce TEXT NOT NULL,verifier TEXT NOT NULL,expires DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS campus_live.oauth_pending(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES campus_live.users(id),expires DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS campus_live.teacher_requests(user_id TEXT PRIMARY KEY REFERENCES campus_live.users(id),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created DOUBLE PRECISION NOT NULL,reviewed DOUBLE PRECISION,reviewer TEXT,decision_note TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS campus_live.lesson_submissions(user_id TEXT NOT NULL REFERENCES campus_live.users(id),lesson_id TEXT NOT NULL,confidence TEXT NOT NULL,difficulty TEXT NOT NULL,comment TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending',feedback TEXT NOT NULL DEFAULT '',revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(user_id,lesson_id));
CREATE TABLE IF NOT EXISTS campus_live.practice_grades(user_id TEXT NOT NULL REFERENCES campus_live.users(id),lesson_id TEXT NOT NULL,score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 10),feedback TEXT NOT NULL DEFAULT '',grader TEXT NOT NULL REFERENCES campus_live.users(id),graded_at DOUBLE PRECISION NOT NULL,PRIMARY KEY(user_id,lesson_id));
CREATE UNIQUE INDEX IF NOT EXISTS campus_single_admin ON campus_live.users(role) WHERE role='admin';
